 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            boxes = {}
            while q:
                y, x = q.popleft()
                color = grid[y][x]
                cells.append((y, x))
                if color not in boxes:
                    boxes[color] = [y, x, y, x]
                else:
                    b = boxes[color]
                    b[0], b[1], b[2], b[3] = min(b[0], y), min(b[1], x), max(b[2], y), max(b[3], x)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            # The nested rectangular color bands are ordered outer-to-inner by bbox area.
            colors = sorted(boxes, key=lambda k: (-(boxes[k][2] - boxes[k][0] + 1) * (boxes[k][3] - boxes[k][1] + 1), k))
            mapping = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out


